//@ProcessingGroup("kYCDocument")
@Component("kYCDocument-projector")
public class KYCDocumentProjector extends KYCDocumentEntityProjector {
		
	// core constructor
	public KYCDocumentProjector(ProjectorRegistry registry,
									KYCDocumentRepository repository,
									QueryUpdateEmitter queryUpdateEmitter ) {
        super(registry, repository);
        this.queryUpdateEmitter = queryUpdateEmitter;
    }	

	/*
     * @param	event CreateKYCDocumentEvent
     */
    @EventHandler( payloadType=CreateKYCDocumentEvent.class )
    public void handle( CreateKYCDocumentEvent event) {
	    LOGGER.info("handling CreateKYCDocumentEvent - " + event );
	    KYCDocument entity = new KYCDocument();
            entity.setKYCDocumentId( event.getKYCDocumentId() );
            entity.setReference( event.getReference() );
            entity.setIssuedCountry( event.getIssuedCountry() );
            entity.setExpirationDate( event.getExpirationDate() );
            entity.setDocumentType( event.getDocumentType() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllKYCDocument( entity );
    }

    /*
     * @param	event UpdateKYCDocumentEvent
     */
    @EventHandler( payloadType=UpdateKYCDocumentEvent.class )
    public void handle( UpdateKYCDocumentEvent event) {
    	LOGGER.info("handling UpdateKYCDocumentEvent - " + event );
    	
	    KYCDocument entity = new KYCDocument();
            entity.setKYCDocumentId( event.getKYCDocumentId() );
            entity.setReference( event.getReference() );
            entity.setIssuedCountry( event.getIssuedCountry() );
            entity.setExpirationDate( event.getExpirationDate() );
            entity.setKycProfile( event.getKycProfile() );
            entity.setDocumentType( event.getDocumentType() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindKYCDocument( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllKYCDocument( entity );        
    }
    
    /*
     * @param	event DeleteKYCDocumentEvent
     */
    @EventHandler( payloadType=DeleteKYCDocumentEvent.class )
    public void handle( DeleteKYCDocumentEvent event) {
    	LOGGER.info("handling DeleteKYCDocumentEvent - " + event );
    	
    	// ------------------------------------------
    	// delete delegation
    	// ------------------------------------------
    	KYCDocument entity = delete( event.getKYCDocumentId() );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllKYCDocument( entity );

    }    

    /*
     * @param	event AssignKycProfileToKYCDocumentEvent
     */
    @EventHandler( payloadType=AssignKycProfileToKYCDocumentEvent.class)
    public void handle( AssignKycProfileToKYCDocumentEvent event) {
	    LOGGER.info("handling AssignKycProfileToKYCDocumentEvent - " + event );

	    // ------------------------------------------
	    // delegate to assignTo
	    // ------------------------------------------
	    KYCDocument entity = assignKycProfile( event.getKYCDocumentId(), event.getAssignment() );

	    // ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindKYCDocument( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllKYCDocument( entity );
    }
    

	/*
	 * @param	event UnAssignKycProfileFromKYCDocumentEvent
	 */
	@EventHandler( payloadType=UnAssignKycProfileFromKYCDocumentEvent.class)
	public void handle( UnAssignKycProfileFromKYCDocumentEvent event) {
	    LOGGER.info("handling UnAssignKycProfileFromKYCDocumentEvent - " + event );

	    // ------------------------------------------
	    // delegate to unAssignFrom
	    // ------------------------------------------
	    KYCDocument entity = unAssignKycProfile( event.getKYCDocumentId() );

		// ------------------------------------------
		// emit to subscribers that find one
		// ------------------------------------------    	
	    emitFindKYCDocument( entity );
	
		// ------------------------------------------
		// emit to subscribers that find all
		// ------------------------------------------    	
	    emitFindAllKYCDocument( entity );
	}




    /**
     * Method to retrieve the KYCDocument via an KYCDocumentPrimaryKey.
     * @param 	id Long
     * @return 	KYCDocument
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public KYCDocument handle( FindKYCDocumentQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getKYCDocumentId() );
    }
    
    /**
     * Method to retrieve a collection of all KYCDocuments
     *
     * @param	query	FindAllKYCDocumentQuery 
     * @return 	List<KYCDocument> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<KYCDocument> handle( FindAllKYCDocumentQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindKYCDocument,
 * but only if the id matches
 *
 * @param		entity	KYCDocument
 */
	protected void emitFindKYCDocument( KYCDocument entity ) {
		LOGGER.info("handling emitFindKYCDocument" );
		
	    queryUpdateEmitter.emit(FindKYCDocumentQuery.class,
	                            query -> query.getFilter().getKYCDocumentId().equals(entity.getKYCDocumentId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllKYCDocument
	 * 
	 * @param		entity	KYCDocument
	 */
	protected void emitFindAllKYCDocument( KYCDocument entity ) {
		LOGGER.info("handling emitFindAllKYCDocument" );
		
	    queryUpdateEmitter.emit(FindAllKYCDocumentQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
	private final QueryUpdateEmitter queryUpdateEmitter;
    private static final Logger LOGGER 	= Logger.getLogger(KYCDocumentProjector.class.getName());

}
